binding.script:
		  if (!getprop("gear/gear[0]/wow")) {
            screen.log.write("This is only possible on ground.");
            return;
          }
          if (getprop("sim/model/f15/chute/done")) {
            setprop("sim/model/f15/chute/repack", 1);
            setprop("sim/model/f15/chute/done", 0);
            setprop("sim/model/f15/chute/enable", 0);
            setprop("sim/model/f15/chute/force", 2);
            setprop("sim/model/f15/chute/fold", 0);
            screen.log.write("Drag chute repacked.");
            setprop("sim/model/f15/chute/repack", 0);
            aircraft.chuteLoop.stop();
          }

if (getprop("payload/armament/station/id-1-type") == "AIM-9X" or getprop("payload/armament/station/id-1-type") == "AIM-120D" or getprop("payload/armament/station/id-1-type") == "CBU-105" or getprop("payload/armament/station/id-1-type") == "AGM-65B" or getprop("payload/armament/station/id-1-type") == "GBU-12" or getprop("payload/armament/station/id-1-type") == "GBU-54" or getprop("payload/armament/station/id-1-type") == "GBU-32") {
	setprop("payload/armament/station/id-1-count", 2);
} elsif (getprop("payload/armament/station/id-1-type") == "MK-83" or getprop("payload/armament/station/id-1-type") == "CBU-87") {
	setprop("payload/armament/station/id-1-count", 3);
} elsif (getprop("payload/armament/station/id-1-type") == "GBU-39") {
	setprop("payload/armament/station/id-1-count", 4);
} else {
	setprop("payload/armament/station/id-1-count", 1);
}

if (getprop("payload/armament/station/id-3-set") == "2 x AIM-120D AMRAAM") {
	setprop("payload/armament/station/id-3-count", 2);
} elsif (getprop("payload/armament/station/id-3-set") == "3 x MK-82 AIR" or getprop("payload/armament/station/id-3-set") == "3 x MK-82") {
	setprop("payload/armament/station/id-3-count", 3);
} elsif (getprop("payload/armament/station/id-3-set") == "4 x GBU-39") {
