if (getprop("sim/multiplay/generic/bool[70]") != 1) {
	setprop("sim/model/f15/warn-loads-text", "!You need conformal fuel tanks to use that hardpoint!");
	var warn_dialog = gui.Dialog.new("dialog[4]","Aircraft/F-15/gui/dialogs/warn-loads.xml");
	warn_dialog.open();
	setprop("payload/weight[18]/selected", "Empty");
}

